21	constexpr int NUM_THREADS = NUM_WARPS * 32;
22	constexpr int PADDED_D = HEAD_DIM + 8;         // pad rows to avoid bank conflicts
23	constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;
24	constexpr int SMEM_BYTES = 4 * TILE_ELEMS * 2;  // K0,V0,K1,V1 only: Q/O live in regs
