26	__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
27	    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
28	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
29	}
30	__device__ __forceinline__ void cp_async_commit() { asm volatile("cp.async.commit_group;\n"); }
31	template<int N> __device__ __forceinline__ void cp_async_wait() {
32	    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
33	}
