35	__device__ __forceinline__ void load_tile(const __nv_bfloat16* src,
36	                                          __nv_bfloat16* dst, int row0,
37	                                          int rows, int seq_len, bool zero_fill) {
38	    constexpr int CHUNKS_PER_ROW = HEAD_DIM / 8;
39	    for (int i = threadIdx.x; i < rows * CHUNKS_PER_ROW; i += NUM_THREADS) {
40	        const int row = i / CHUNKS_PER_ROW, col8 = i % CHUNKS_PER_ROW;
41	        const int grow = row0 + row;
42	        __nv_bfloat16* s = dst + row * PADDED_D + col8 * 8;
43	        if (grow < seq_len) cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
44	        else if (zero_fill) *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
45	    }
46	}
